import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/api/scope-identity.html","title":"范围身份、删除与同名重建","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1793083391000,"contributors":[{"name":"之旸 刘","username":"","email":"marufyurisa@outlook.com","commits":1}],"changelog":[{"hash":"a7bc7e5f74740c184e03fa5817e5e4576113490b","time":1793083391000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: integrate release workflows, managed backups and runtime fixes"}]},"filePathRelative":"api/scope-identity.md"}`),u={name:`scope-identity.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[5]||=i(`h1`,{id:`范围身份、删除与同名重建`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#范围身份、删除与同名重建`},`#`),e(` 范围身份、删除与同名重建`)],-1),i(`p`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`返回 API 入口`,-1)]]),_:1}),l[3]||=e(` · `,-1),a(m,{to:`/api/backup.html`},{default:r(()=>[...l[1]||=[e(`整机业务备份`,-1)]]),_:1}),l[4]||=e(` · `,-1),a(m,{to:`/api/transfer-export.html`},{default:r(()=>[...l[2]||=[e(`导出来源`,-1)]]),_:1})]),l[6]||=n(`<p>本页对应“解锁后删除环境/渠道并允许同名重建”的后端合同。业务 key（<code>environment_key</code>/<code>pipeline_key</code>）继续用于展示和兼容调用，但不再是数据库唯一身份；每一代范围都有独立的 <code>environment_id</code> / <code>scope_id</code>。</p><h2 id="_1-身份字段" tabindex="-1"><a class="header-anchor" href="#_1-身份字段">#</a> 1. 身份字段</h2><table><thead><tr><th>对象</th><th>字段</th></tr></thead><tbody><tr><td>环境</td><td><code>environment_id</code>（UUID，每次创建新值）</td></tr><tr><td>渠道</td><td><code>scope_id</code>、<code>environment_id</code></td></tr><tr><td>配置、资源</td><td><code>scope_id</code></td></tr><tr><td>冻结状态/事件</td><td><code>scope_id</code></td></tr><tr><td>发布版本/生效指针/事件</td><td><code>scope_id</code></td></tr></tbody></table><p>删除后 <code>active_slot</code> 置空，旧行保留 <code>deleted_at</code>；同一业务 key 再创建时插入新行、新 UUID，不复用旧行，也不继承旧配置、资源、freeze/head 或版本。</p><h2 id="_2-读取合同" tabindex="-1"><a class="header-anchor" href="#_2-读取合同">#</a> 2. 读取合同</h2><ul><li>环境 list/detail/create/update 返回 <code>environment_id</code>。</li><li>渠道 list/detail/create/update、runtime overview 返回 <code>scope_id</code> 和 <code>environment_id</code>。</li><li>配置、资源、freeze、release 元数据返回 <code>scope_id</code>。</li><li>管理列表/详情可选传 <code>scope_id</code> 定位当前代；传旧代返回 410 <code>SCOPE_DELETED</code>，不会回退到同名新代。</li><li>未携带身份键的运行时调用继续解析当前有效范围；同名重建后会读取新范围。需要长期固定的调用方应使用 <code>scope_id</code>/<code>snapshot_id</code>。</li><li>旧 <code>snapshot_id</code>/<code>file_id</code> 属于旧代，范围删除后新请求返回 410。</li></ul><h2 id="_3-删除接口" tabindex="-1"><a class="header-anchor" href="#_3-删除接口">#</a> 3. 删除接口</h2><h3 id="删除环境" tabindex="-1"><a class="header-anchor" href="#删除环境">#</a> 删除环境</h3><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/environment/delete</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_environment_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;11111111-1111-4111-8111-111111111111&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>只检查<strong>当前有效渠道</strong>是否锁版；任一 locked 返回 409 <code>SCOPE_FROZEN</code>，整体不删除。</li><li>全部解锁即可删除，不再因为生效版本、历史版本或已删版本存在而阻止。</li><li>删除事务内：环境与有效渠道置逻辑删除，配置/原始资源逻辑删除，未删除版本补 <code>scope_deleted</code> 删除标记，清空生效指针，保留冻结/发布历史，写范围删除审计。</li><li>文件不立即删除。</li></ul><p>成功：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;OK&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;deleted&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;environment_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;deleted_at&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2026-10-25T02:00:00Z&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;pipelines&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;configs&quot;</span><span class="token operator">:</span> <span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;assets&quot;</span><span class="token operator">:</span> <span class="token number">4</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;versions&quot;</span><span class="token operator">:</span> <span class="token number">3</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="删除渠道" tabindex="-1"><a class="header-anchor" href="#删除渠道">#</a> 删除渠道</h3><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/pipeline/delete</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;22222222-2222-4222-8222-222222222222&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只检查自身冻结状态，不影响其他渠道或环境名称。</p><h3 id="身份与错误" tabindex="-1"><a class="header-anchor" href="#身份与错误">#</a> 身份与错误</h3><table><thead><tr><th>HTTP</th><th>error_type</th><th>场景</th></tr></thead><tbody><tr><td>400</td><td><code>SCOPE_INVALID_REQUEST</code></td><td>缺少/非法身份 UUID</td></tr><tr><td>404</td><td><code>SCOPE_NOT_FOUND</code></td><td>业务 key 从未存在</td></tr><tr><td>409</td><td><code>SCOPE_IDENTITY_CONFLICT</code></td><td>同 key 已重建，身份不同</td></tr><tr><td>410</td><td><code>SCOPE_DELETED</code></td><td>指定身份已删除</td></tr><tr><td>409</td><td><code>SCOPE_FROZEN</code></td><td>有待删除的有效渠道仍 locked</td></tr></tbody></table><p>删除请求没有 <code>request_id</code>；结果丢失后查询对象身份，禁止仅凭同 key 再次自动删除。</p><h2 id="_4-写入必须携带身份" tabindex="-1"><a class="header-anchor" href="#_4-写入必须携带身份">#</a> 4. 写入必须携带身份</h2><ul><li>更新环境、创建渠道：<code>expected_environment_id</code>。</li><li>修改/删除渠道，以及配置创建/更新/删除、资源上传、freeze lock/unlock、release create/activate/delete：<code>expected_scope_id</code>。</li><li>服务层先校验 UUID 与当前身份匹配，再执行原有 edit/freeze/head revision 与 request_id 规则；不能只在 Handler 比较，也不能缺省跳过。</li><li>旧请求命中旧 scope 返回 410，命中同名新 scope 的身份不符返回 409；即使数字 revision 相同也不会修改新对象。</li><li>导入/迁移在写协调内解析目标身份一次并绑定整个操作；归档里的来源身份只用于追溯，不作为目标身份落库。</li></ul><h2 id="_5-默认对象与启动迁移" tabindex="-1"><a class="header-anchor" href="#_5-默认对象与启动迁移">#</a> 5. 默认对象与启动迁移</h2><ul><li>启动时先完成身份回填、索引替换，再开放 HTTP。</li><li>已有行获得稳定身份；无法唯一判定归属或存在冲突时拒绝启动并输出脱敏诊断，不猜测写入。</li><li>默认环境/渠道只在从未初始化的数据库创建。用户删除后重启不会复活；用户显式创建同名 <code>default</code> 会得到全新身份。</li><li>旧版索引（<code>uk_environment_key</code>、<code>uk_env_pipeline</code>、<code>uk_config_resource</code>、<code>uk_freeze_scope</code>、<code>uk_release_scope_version</code>、<code>uk_release_head_scope</code>）由迁移移除，并创建按身份的约束与别名唯一索引。</li></ul><h2 id="_6-与备份恢复" tabindex="-1"><a class="header-anchor" href="#_6-与备份恢复">#</a> 6. 与备份恢复</h2><ul><li>备份 schema_version 当前为 <code>3</code>：schema 2 的范围身份（含已删除 scope、<code>active_slot</code>、删除审计）加上 <code>config_release_head.last_version_number</code>。</li><li>schema 1 旧包仍可恢复：在隔离候选库中先按旧白名单校验，再执行确定性身份回填，并补编号列/回填计数后按 schema 3 校验/恢复；不执行包内 DDL。</li><li>schema 2 包仍可恢复：先按 schema 2 白名单校验，再在隔离候选库补编号列并用历史 <code>vN</code> 回填；旧二进制不能读取 schema 3 包。</li><li>恢复后所有配置重新生成 <code>edit_revision</code>；管理员账号保留、旧会话失效。</li></ul>`,24)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};